import vn.rtr.aeris.cockpit03.PresentationGate;public class PresentationQA{static int n;static void check(boolean b){if(!b)throw new AssertionError("P"+n);n++;}public static void main(String[]a)throws Exception{PresentationGate g=new PresentationGate();check(!g.ready());check(g.chosen().equals("survey"));g.acknowledge("survey");check(g.ready());check(!g.choose("survey")&&g.ready());check(g.choose("preflight")&&!g.ready());try{g.acknowledge("survey");throw new AssertionError();}catch(java.io.IOException ok){}check(!g.ready());g.acknowledge("preflight");check(g.ready());g.choose("fly");check(!g.ready());try{g.acknowledge("preflight");throw new AssertionError();}catch(java.io.IOException ok){}g.acknowledge("fly");check(g.ready());check(!g.choose("fly")&&g.ready());g.choose("review");check(!g.ready());try{g.choose("ARM");throw new AssertionError();}catch(IllegalArgumentException ok){}check(g.chosen().equals("review"));System.out.println("{\"status\":\"PASS\",\"assertions\":"+n+"}");}}
